# -*- coding: utf-8 -*-
"""独立自检：从磁盘重读候选 JSON，把里面所有 quote/start/end 条目逐条回切校验。

判据（任一不成立即计入 bad）：
  * docs[0].text[start:end] == quote                 （逐字）
  * sourceHash == 任务 sourceHash                     （哈希口径）
  * docs[0].text.count(quote) == 1                    （全文唯一）
  * 区间内引用：切片内 count == 1 且 [start,end) ⊆ [65082,68044)
  * 区间外引用：crossRange is True 且切片内 count == 0
  * 文件哈希 == 任务 sourceHash

运行：python3 /tmp/wk21/verify_0021.py
"""
import hashlib
import json
import sys

ROOT = '/Users/carmen/Desktop/星系'
SRC = 'fdde555867aaccc2e676da9e9f3afecceab5d56114ae3e236af089e712539839'
S, E = 65082, 68044
CAND = ROOT + '/loop/state/out/read_dafeng_L1_0021.candidate.json'

raw = open(ROOT + '/data/cache/9b676d7031b1bcd3b8377a18.docs.json', 'rb').read()
file_hash = hashlib.sha256(raw).hexdigest()
TEXT = json.loads(raw.decode('utf-8'))[0]['text']
SEG = TEXT[S:E]
cand = json.load(open(CAND, encoding='utf-8'))

refs = []


def walk(o, path='$'):
    if isinstance(o, dict):
        if 'quote' in o and 'start' in o and 'end' in o:
            refs.append((path, o))
        for k, v in o.items():
            walk(v, path + '.' + str(k))
    elif isinstance(o, list):
        for i, v in enumerate(o):
            walk(v, path + '[%d]' % i)


walk(cand)

bad = []
in_range = cross_range = 0
for path, o in refs:
    q = o['quote']
    st, en = o['start'], o['end']
    if TEXT[st:en] != q:
        bad.append(('not-verbatim', path, st, en))
    if TEXT.count(q) != 1:
        bad.append(('not-unique', path, TEXT.count(q)))
    if o.get('sourceHash') != SRC:
        bad.append(('bad-sourceHash', path, o.get('sourceHash')))
    if o.get('offsetUnit') != 'codepoint':
        bad.append(('bad-offsetUnit', path, o.get('offsetUnit')))
    if o.get('inWholeTextOccurrences') != TEXT.count(q):
        bad.append(('bad-wholeCount', path, o.get('inWholeTextOccurrences')))
    inside = S <= st and en <= E
    if inside:
        in_range += 1
        if SEG.count(q) != 1:
            bad.append(('in-seg-not-unique', path, SEG.count(q)))
        if o.get('crossRange') is not False:
            bad.append(('in-range-but-crossRange-not-false', path, o.get('crossRange')))
        if o.get('inSegmentOccurrences') != 1:
            bad.append(('bad-inSegCount', path, o.get('inSegmentOccurrences')))
    else:
        cross_range += 1
        if SEG.count(q) != 0:
            bad.append(('cross-range-appears-in-seg', path, SEG.count(q)))
        if o.get('crossRange') is not True:
            bad.append(('cross-range-flag-missing', path, o.get('crossRange')))

print('file_hash == task sourceHash :', file_hash == SRC)
print('slice head                   :', repr(SEG[:14]))
print('slice len                    :', len(SEG))
print('quotes                       :', len(refs))
print('  in-range                   :', in_range)
print('  cross-range                :', cross_range)
print('bad                          :', len(bad))
for b in bad:
    print('   ', b)

# 结构字段自检
need = ['tasks', 'causeEdges', 'states', 'foreshadows', 'unknowns', 'selfCritique']
for k in need:
    v = cand.get(k)
    print('field %-14s : %s' % (k, ('%d 条' % len(v)) if isinstance(v, list) else type(v).__name__))

# 五元组缺项必须是 null 而不是编造值
for t in cand['tasks']:
    for f in ['objective', 'obstacle', 'action', 'result', 'cost']:
        if f not in t:
            print('  ! task %s 缺字段 %s' % (t['id'], f))
        elif t[f] is None:
            print('  ~ task %s 的 %s 为 null' % (t['id'], f))

# basis 取值合法性
legal = {'explicit', 'inferred', 'derived', 'unverified'}
for k in ['tasks', 'causeEdges', 'states', 'foreshadows', 'unknowns', 'rejectedCauseEdges', 'rejectedForeshadows']:
    for item in cand.get(k) or []:
        b = item.get('basis')
        if isinstance(b, dict):
            for kk, vv in b.items():
                if vv not in legal:
                    print('  ! basis 非法 %s.%s.%s=%r' % (k, item.get('id'), kk, vv))
        elif b is not None and b not in legal:
            print('  ! basis 非法 %s.%s=%r' % (k, item.get('id'), b))
        elif b is None and k in ('causeEdges', 'states', 'unknowns'):
            print('  ! %s.%s 缺 basis' % (k, item.get('id')))

# 伏笔必须有铺设+回收；未回收必须显式 unresolved
for f in cand['foreshadows']:
    ok = ('setup' in f) and (('payoff' in f))
    st = f.get('status')
    if not ok:
        print('  ! 伏笔 %s 缺 setup/payoff 字段' % f['id'])
    if f.get('payoff') is None and 'unresolved' not in (st or ''):
        print('  ! 伏笔 %s payoff=null 但 status=%r 未标 unresolved' % (f['id'], st))

# 语义复核不得写成已完成
rs = cand.get('reviewStatus') or {}
if rs.get('semanticReview') != 'not-performed':
    print('  ! semanticReview 被写成已完成：%r' % rs.get('semanticReview'))
else:
    print('semanticReview               : not-performed (OK)')

# 构建脚本自己记录的 failures 必须为空
sc = cand.get('selfCheck') or {}
print('selfCheck.failures           :', sc.get('failures'))

sys.exit(1 if bad else 0)
